32. const matchRoute = (route, fetchArgs) => {
33.   const url = fetchArgs[0];
34.   const options = fetchArgs[1];
35. 
36.   const method = options && options.method ? options.method : 'GET';
37.   const body = options && options.body;
38.   const routeBody = route.body;
39. 
40.   let bodyMatch = false;
41.   if (routeBody?.encoding === 'base64' && ['File', 'Blob'].includes(body?.constructor.name)) {
42.     const blob = new Blob([Buffer.from(routeBody.content, 'base64')], {
43.       type: routeBody.contentType,
44.     });
45.     // size matching is good enough
46.     bodyMatch = blob.size === body.size;
47.   } else if (routeBody && body?.constructor.name === 'FormData') {
48.     bodyMatch = Array.from(body.entries()).some(([key, value]) => {
49.       const val = typeof value === 'string' ? value : '';
50.       const match = routeBody.includes(key) && routeBody.includes(val);
51.       return match;
52.     });
53.   } else {
54.     bodyMatch = body === routeBody;
55.   }
56. 
57.   // use pattern matching for the timestamp parameter
58.   const urlRegex = escapeRegExp(decodeURIComponent(route.url)).replace(
59.     /ts=\d{1,15}/,
60.     'ts=\\d{1,15}',
61.   );
62. 
63.   return (
64.     method === route.method && bodyMatch && decodeURIComponent(url).match(new RegExp(`${urlRegex}`))
